"use client";

import { readApiResponse } from "../lib/api-response";

import { useCallback, useEffect, useMemo, useState } from "react";

type Client = { id:string; name:string; phone:string; email:string; status:string; service:string; monthlyFeeCents:number; feeFrozen:number;  paymentMethod:string; frequency:string; scheduleType:string; trainingSchedule:string; startDate:string; nextReviewDate:string; importantNotes:string; goal:string; trainingNotes:string; trainingMetrics:string; physioNotes:string; testimonialConsent:number };
type Lead = { id:string; name:string; contact:string; source:string; objective:string; stage:string; nextActionDate:string; notes:string };
type Checkin = { id:string; clientId:string; sessionDate:string; sessionType:string; attendance:string; effort:number|null; satisfaction:number|null; discomfort:number|null; notes:string; nextAction:string };
type Task = { id:string; clientId:string|null; leadId:string|null; title:string; dueDate:string; status:string; notes:string };
type Transaction = { id:string; transactionDate:string; direction:string; category:string; amountCents:number; description:string; clientId:string|null; servicePeriod:string; paymentMethod:string; reference:string; reconciled:number };
type MonthlyDue = { id:string; clientId:string; servicePeriod:string; amountDueCents:number };
type CrossSellOffer = { id:string; name:string; category:string; status:string; unitPriceCents:number; unitCostCents:number; expectedUnits:number; initialInvestmentCents:number; notes:string };
type SupplementPlan = { id:string; servicePeriod:string; investmentCents:number };
type TanitaAssessment = { id:string; clientId:string; assessmentDate:string; weightKg:number|null; bodyFatPercent:number|null; muscleMassKg:number|null; visceralFat:number|null; bmi:number|null; basalMetabolismKcal:number|null; bodyWaterPercent:number|null; priceCents:number; paid:number; paymentMethod:string; notes:string };
type ProfessionalNote = { id:string; clientId:string; professionalRole:string; note:string; createdAt:string };
type Dataset = { clients:Client[]; leads:Lead[]; checkins:Checkin[]; tasks:Task[]; transactions:Transaction[]; monthlyDues:MonthlyDue[]; crossSellOffers:CrossSellOffer[]; supplementPlans:SupplementPlan[]; tanitaAssessments:TanitaAssessment[]; professionalNotes:ProfessionalNote[] };
type Modal = "client"|"lead"|"transaction"|"checkin"|"task"|"crossSell"|"tanita"|null;
const emptyData:Dataset={clients:[],leads:[],checkins:[],tasks:[],transactions:[],monthlyDues:[],crossSellOffers:[],supplementPlans:[],tanitaAssessments:[],professionalNotes:[]};
const services:[string,string][]=[["Entrenamiento en grupos reducidos","Entrenamiento en grupos reducidos"],["Entrenamiento personal","Entrenamiento personal"]];
const goals=["Pérdida de grasa","Salud y bienestar","Rehabilitación de lesiones","Hipertrofia","Mejora del rendimiento deportivo","Otro objetivo específico"];
const stages:[string,string][]=[["nuevo","Nuevo"],["contactado","Contactado"],["valoracion","Valoración"],["propuesta","Propuesta"],["seguimiento","Seguimiento"],["ganado","Convertido"],["perdido","Descartado"]];
const today=()=>{const d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10)};
const monthNow=()=>today().slice(0,7);
const money=(c:number)=>new Intl.NumberFormat("es-ES",{style:"currency",currency:"EUR"}).format((c||0)/100);
const dateLabel=(v?:string|null)=>!v?"—":/^\d{4}-\d{2}$/.test(v)?new Date(v+"-15T12:00:00").toLocaleDateString("es-ES",{month:"long",year:"numeric"})+" · día no indicado":new Date(v+"T12:00:00").toLocaleDateString("es-ES",{day:"2-digit",month:"short",year:"numeric"});
const euros=(v:string)=>Math.round((Number(v.replace(",","."))||0)*100);
const frequencyLabel=(value:string)=>value?`${value} ${value==="1"?"día":"días"} / semana`:"—";

export function CrmShell({userEmail}:{userEmail:string}) {
  const [data,setData]=useState<Dataset>(emptyData),[page,setPage]=useState("inicio"),[modal,setModal]=useState<Modal>(null);
  const [editing,setEditing]=useState<Client|null>(null),[editingOffer,setEditingOffer]=useState<CrossSellOffer|null>(null),[selected,setSelected]=useState<Client|null>(null),[search,setSearch]=useState("");
  const [month,setMonth]=useState(monthNow()),[loading,setLoading]=useState(true),[saving,setSaving]=useState(false);
  const [loggingOut,setLoggingOut]=useState(false);
  const [supplementDraft,setSupplementDraft]=useState<{month:string;plans:SupplementPlan[];value:string}|null>(null);
  const [error,setError]=useState(""),[notice,setNotice]=useState(""),[form,setForm]=useState<Record<string,string|boolean>>({});
  const load=useCallback((signal?:AbortSignal)=>fetch("/api/crm?month="+month,{cache:"no-store",signal})
    .then(r=>readApiResponse<Dataset>(r,"No se pudo cargar el CRM."))
    .then(next=>{if(!signal?.aborted){setData(next);setError("");}})
    .catch((e:unknown)=>{if(!signal?.aborted)setError(e instanceof Error?e.message:"No se pudo cargar el CRM.");})
    .finally(()=>{if(!signal?.aborted)setLoading(false);}),[month]);
  useEffect(()=>{const controller=new AbortController();void load(controller.signal);return ()=>controller.abort();},[load]);
  const clientMap=useMemo(()=>new Map(data.clients.map(c=>[c.id,c])),[data.clients]);
  const leadMap=useMemo(()=>new Map(data.leads.map(l=>[l.id,l])),[data.leads]);
  const active=data.clients.filter(c=>c.status==="active");
  const monthTx=data.transactions.filter(t=>t.transactionDate.startsWith(month));
  const cashIn=monthTx.filter(t=>t.direction==="entrada").reduce((s,t)=>s+t.amountCents,0);
  const cashOut=monthTx.filter(t=>t.direction==="salida").reduce((s,t)=>s+t.amountCents,0);
  const expected=data.monthlyDues.reduce((s,d)=>s+d.amountDueCents,0);
  const monthlyPaid=data.transactions.filter(t=>t.direction==="entrada"&&t.category==="Cuota mensual"&&t.servicePeriod===month).reduce((s,t)=>s+t.amountCents,0);
  const paidByClient=new Map<string,number>();
  data.transactions.filter(t=>t.direction==="entrada"&&t.category==="Cuota mensual"&&t.servicePeriod===month&&t.clientId).forEach(t=>paidByClient.set(t.clientId!, (paidByClient.get(t.clientId!)||0)+t.amountCents));
  const unpaid=data.monthlyDues.filter(d=>(paidByClient.get(d.clientId)||0)<d.amountDueCents).map(d=>({due:d,client:clientMap.get(d.clientId)!})).filter(x=>x.client);
  const tasks=data.tasks.filter(t=>t.status!=="hecha").sort((a,b)=>a.dueDate.localeCompare(b.dueDate));
  const projectedOffers=data.crossSellOffers.filter(o=>o.status==="activa"||o.status==="planificada");
  const projectedRevenue=projectedOffers.reduce((sum,o)=>sum+o.unitPriceCents*o.expectedUnits,0);
  const projectedVariableCost=projectedOffers.reduce((sum,o)=>sum+o.unitCostCents*o.expectedUnits,0);
  const projectedMargin=projectedRevenue-projectedVariableCost;
  const plannedInvestment=data.crossSellOffers.filter(o=>o.status!=="archivada").reduce((sum,o)=>sum+o.initialInvestmentCents,0);
  const supplementPlan=data.supplementPlans.find(item=>item.servicePeriod===month);
  const supplementInvestment=supplementDraft?.month===month&&supplementDraft.plans===data.supplementPlans
    ? supplementDraft.value : supplementPlan?String(supplementPlan.investmentCents/100):"";
  const supplementInvestmentCents=euros(supplementInvestment);
  const supplementReturnCents=supplementInvestmentCents*2;
  const supplementProfitCents=supplementReturnCents-supplementInvestmentCents;
  const q=search.trim().toLocaleLowerCase("es");
  const filtered=data.clients.filter(c=>!q||(c.name+" "+c.phone+" "+c.email+" "+c.service).toLocaleLowerCase("es").includes(q))
    .sort((a,b)=>{
      const statusRank=(status:string)=>status==="active"?0:status==="paused"?1:2;
      return statusRank(a.status)-statusRank(b.status)||a.name.localeCompare(b.name,"es",{sensitivity:"base"});
    });
  const formValue=(key:string,fallback="")=>String(form[key]??fallback);
  const field=(key:string,value:string|boolean)=>setForm(p=>({...p,[key]:value}));
  function open(kind:Modal,initial:Record<string,string|boolean>={}){setError("");setNotice("");setForm(initial);setEditing(null);setEditingOffer(null);setModal(kind);}
  function openTanita(client:Client){setSelected(client);open("tanita",{clientId:client.id,assessmentDate:today(),paid:false,paymentMethod:client.paymentMethod||"efectivo"});}
  function openClient(c?:Client){setError("");setNotice("");setSelected(null);setEditing(c||null);setForm(c?{name:c.name,phone:c.phone,email:c.email,status:c.status,service:c.service,monthlyFee:String(c.monthlyFeeCents/100),feeFrozen:!!c.feeFrozen,paymentMethod:c.paymentMethod||"efectivo",frequency:c.frequency,scheduleType:c.scheduleType||"fijo",trainingSchedule:c.trainingSchedule||"",startDate:c.startDate,nextReviewDate:c.nextReviewDate,importantNotes:c.importantNotes||"",goal:c.goal,trainingNotes:c.trainingNotes,trainingMetrics:c.trainingMetrics||"",physioNotes:c.physioNotes||"",testimonialConsent:!!c.testimonialConsent}:{status:"active",paymentMethod:"efectivo",scheduleType:"fijo",startDate:today(),monthlyFee:"",feeFrozen:false,testimonialConsent:false});setModal("client");}
  function openOffer(offer?:CrossSellOffer){setError("");setNotice("");setSelected(null);setEditing(null);setEditingOffer(offer||null);setForm(offer?{name:offer.name,category:offer.category,status:offer.status,unitPrice:String(offer.unitPriceCents/100),unitCost:String(offer.unitCostCents/100),expectedUnits:String(offer.expectedUnits),initialInvestment:String(offer.initialInvestmentCents/100),notes:offer.notes}:{name:"",category:"otro",status:"planificada",unitPrice:"",unitCost:"0",expectedUnits:"0",initialInvestment:"0",notes:""});setModal("crossSell");}
  async function save(entity:string,payload:Record<string,unknown>,id?:string){setSaving(true);setError("");setNotice("");try{const r=await fetch("/api/crm",{method:id?"PATCH":"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({entity,id,data:payload})});await readApiResponse(r,"No se pudo guardar.");await load();setNotice("Guardado correctamente.");setModal(null);setSelected(null);}catch(e){setError(e instanceof Error?e.message:"No se pudo guardar.");}finally{setSaving(false);}}
  async function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();
    if(modal==="client")await save("client",{name:formValue("name"),phone:formValue("phone"),email:formValue("email"),status:formValue("status","active"),service:formValue("service"),monthlyFeeCents:euros(formValue("monthlyFee")),feeFrozen:!!form.feeFrozen,paymentMethod:formValue("paymentMethod","efectivo"),frequency:formValue("frequency"),scheduleType:formValue("scheduleType","fijo"),trainingSchedule:formValue("trainingSchedule"),startDate:formValue("startDate"),nextReviewDate:formValue("nextReviewDate"),importantNotes:formValue("importantNotes"),goal:formValue("goal"),trainingNotes:formValue("trainingNotes"),trainingMetrics:formValue("trainingMetrics"),physioNotes:formValue("physioNotes"),testimonialConsent:!!form.testimonialConsent},editing?.id);
    if(modal==="lead")await save("lead",{name:formValue("name"),contact:formValue("contact"),source:formValue("source"),objective:formValue("objective"),stage:formValue("stage","nuevo"),nextActionDate:formValue("nextActionDate"),notes:formValue("notes")});
    if(modal==="transaction")await save("transaction",{transactionDate:formValue("transactionDate",today()),direction:formValue("direction","entrada"),category:formValue("category","Cuota mensual"),amountCents:euros(formValue("amount")),description:formValue("description"),clientId:formValue("clientId"),servicePeriod:formValue("servicePeriod"),paymentMethod:formValue("paymentMethod","efectivo"),reference:formValue("reference")});
    if(modal==="checkin")await save("checkin",{clientId:formValue("clientId"),sessionDate:formValue("sessionDate",today()),sessionType:formValue("sessionType","Entrenamiento"),attendance:formValue("attendance","realizada"),effort:formValue("effort"),satisfaction:formValue("satisfaction"),discomfort:formValue("discomfort"),notes:formValue("notes"),nextAction:formValue("nextAction"),followupDate:formValue("followupDate"),followupTitle:formValue("followupTitle")});
    if(modal==="task")await save("task",{title:formValue("title"),dueDate:formValue("dueDate",today()),clientId:formValue("clientId"),leadId:formValue("leadId"),notes:formValue("notes")});
    if(modal==="crossSell")await save("cross_sell_offer",{name:formValue("name"),category:formValue("category","otro"),status:formValue("status","planificada"),unitPriceCents:euros(formValue("unitPrice")),unitCostCents:euros(formValue("unitCost")),expectedUnits:Math.max(0,Math.floor(Number(formValue("expectedUnits"))||0)),initialInvestmentCents:euros(formValue("initialInvestment")),notes:formValue("notes")},editingOffer?.id);
    if(modal==="tanita")await saveTanita();
  }
  async function saveTanita(){if(!selected)return;setSaving(true);setError("");try{const r=await fetch("/api/crm",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({entity:"tanita_assessment",data:{clientId:selected.id,assessmentDate:formValue("assessmentDate",today()),weightKg:formValue("weightKg"),bodyFatPercent:formValue("bodyFatPercent"),muscleMassKg:formValue("muscleMassKg"),visceralFat:formValue("visceralFat"),bmi:formValue("bmi"),basalMetabolismKcal:formValue("basalMetabolismKcal"),bodyWaterPercent:formValue("bodyWaterPercent"),notes:formValue("tanitaNotes"),paid:!!form.paid,paymentMethod:formValue("paymentMethod","efectivo")}})});await readApiResponse(r,"No se pudo guardar la valoración.");await load();setNotice("Valoración Tanita guardada en la ficha del cliente.");setModal(null);}catch(e){setError(e instanceof Error?e.message:"No se pudo guardar la valoración.");}finally{setSaving(false);}}
  async function setTaskDone(t:Task){await save("task",{status:"hecha"},t.id);}
  async function setStage(l:Lead,stage:string){await save("lead",{...l,stage},l.id);}
  async function archiveOffer(offer:CrossSellOffer){await save("cross_sell_offer",{...offer,status:"archivada"},offer.id);}
  async function toggleStatus(c:Client){await save("client",{name:c.name,phone:c.phone,email:c.email,status:c.status==="inactive"?"active":"inactive",service:c.service,monthlyFeeCents:c.monthlyFeeCents,feeFrozen:!!c.feeFrozen,paymentMethod:c.paymentMethod||"efectivo",frequency:c.frequency,scheduleType:c.scheduleType||"fijo",trainingSchedule:c.trainingSchedule||"",startDate:c.startDate,nextReviewDate:c.nextReviewDate,importantNotes:c.importantNotes||"",goal:c.goal,trainingNotes:c.trainingNotes,trainingMetrics:c.trainingMetrics||"",physioNotes:c.physioNotes||"",testimonialConsent:!!c.testimonialConsent},c.id);}
  async function deleteClient(c:Client){if(!window.confirm(`¿Eliminar definitivamente la ficha de ${c.name}? Se borrarán sus notas clínicas, valoraciones y tareas asociadas. Los movimientos de caja se conservarán sin asociarlos a este cliente.`))return;setSaving(true);setError("");setNotice("");try{const r=await fetch("/api/crm",{method:"DELETE",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:c.id})});await readApiResponse(r,"No se pudo eliminar el cliente.");if(selected?.id===c.id)setSelected(null);await load();setNotice(`Ficha de ${c.name} eliminada.`);}catch(e){setError(e instanceof Error?e.message:"No se pudo eliminar el cliente.");}finally{setSaving(false);}}
  function exportBackup(){const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),...data},null,2)],{type:"application/json"});const u=URL.createObjectURL(blob);const a=document.createElement("a");a.href=u;a.download="helzone-crm-backup-"+today()+".json";a.click();URL.revokeObjectURL(u);}
  async function logout(){setLoggingOut(true);setError("");try{const response=await fetch("/api/access",{method:"DELETE",cache:"no-store"});if(!response.ok)throw new Error("No se pudo cerrar la sesión.");window.location.replace("/");}catch(e){setError(e instanceof Error?e.message:"No se pudo cerrar la sesión.");setLoggingOut(false);}}
  const nav:[string,string,string][]=[["inicio","Resumen","⌂"],["clientes","Clientes","◉"],["pagos","Pagos del mes","€"],["tareas","Tareas","✓"],["leads","Captación","＋"],["caja","Caja","€"],["venta-cruzada","Venta cruzada","＋"],["suplementacion","Suplementación","＋"]];

  return <div className="crm-app">
    <aside className="sidebar"><div className="brand"><div className="brand-mark">H</div><div><strong>HELZ-ONE</strong><span>PERSONAL TRAINING</span></div></div><div className="side-label">GESTIÓN DEL CENTRO</div><nav>{nav.map(([id,label,icon])=><button key={id} className={"nav-link "+(page===id?"selected":"")} onClick={()=>{setPage(id);setSearch("");setSelected(null);}}><span className="nav-icon">{icon}</span><span>{label}</span>{id==="clientes"&&active.length>0&&<span className="nav-count">{active.length}</span>}{id==="seguimiento"&&tasks.length>0&&<span className="nav-count alert-count">{tasks.length}</span>}</button>)}</nav><div className="sidebar-bottom"><div className="account-chip"><span className="account-dot"/><span className="account-email">{userEmail}</span></div><button className="text-button" onClick={exportBackup}>↓ Exportar copia de seguridad</button><button className="text-button" onClick={()=>void logout()} disabled={loggingOut}>{loggingOut?"Cerrando sesión…":"Cerrar sesión"}</button></div></aside>
    <main className="main-area"><header className="topbar"><div className="mobile-brand"><span className="brand-mark small">H</span><strong>HELZ-ONE</strong></div><div className="breadcrumb">CENTRO <span>/</span> {(nav.find(x=>x[0]===page)?.[1]||"CLIENTE").toUpperCase()}</div><div className="top-actions"><span className="sync-status"><i/>Nube privada</span><button className="button button-primary button-small" onClick={()=>openClient()}>＋ Nuevo cliente</button></div></header>
      <div className="page-wrap">{error&&!modal&&<div className="notice notice-error">{error}<button onClick={()=>void load()}>Reintentar</button></div>}{notice&&<div className="notice notice-success">{notice}</div>}
        {loading?<div className="loading"><span className="spinner"/> Cargando Helz-One CRM…</div>:<>
          {page==="inicio"&&<section><div className="page-heading"><div><div className="eyebrow">PANEL DE CONTROL · {new Date(month+"-15").toLocaleDateString("es-ES",{month:"long",year:"numeric"}).toUpperCase()}</div><h1>Buenos días, Javier.</h1><p>Una vista clara de clientes, seguimiento y caja.</p></div><input className="month-input" type="month" value={month} onChange={e=>{setLoading(true);setMonth(e.target.value);}}/></div>
            <div className="metrics"><Metric label="Clientes activos" value={String(active.length)} detail={data.clients.filter(c=>c.status==="paused").length+" en pausa"} icon="◉"/><Metric label="Cobrado este mes" value={money(cashIn)} detail={money(monthlyPaid)+" en cuotas mensuales"} icon="↘" gold/><Metric label="Gastos registrados" value={money(cashOut)} detail="Movimientos de caja" icon="↗"/><Metric label="Neto de caja" value={money(cashIn-cashOut)} detail="Entradas menos salidas" icon="＝" gold/></div>
            <div className="dashboard-grid"><div className="panel"><div className="panel-head"><div><h2>Alertas y tareas</h2><p>Cuotas pendientes y acciones anotadas</p></div><button className="link-button" onClick={()=>setPage("tareas")}>Ver tareas →</button></div><div className="attention-list">
              <div className="attention-summary"><span><b>{unpaid.length}</b> cuotas pendientes</span><span><b>{tasks.length}</b> tareas pendientes</span></div>
              {unpaid.slice(0,4).map(({due,client:c})=><div className="attention-row" key={"pay"+c.id}><span className="attention-icon amber">€</span><div><strong>{c.name}</strong><small>Cuota de {month} pendiente · {money(Math.max(0,due.amountDueCents-(paidByClient.get(c.id)||0)))}</small></div><button onClick={()=>open("transaction",{direction:"entrada",category:"Cuota mensual",clientId:c.id,amount:((due.amountDueCents-(paidByClient.get(c.id)||0))/100).toFixed(2),servicePeriod:month,transactionDate:today(),paymentMethod:c.paymentMethod})}>Registrar cobro</button></div>)}
              {tasks.slice(0,5).map(t=><div className="attention-row" key={t.id}><span className="attention-icon gold">✓</span><div><strong>{t.title}</strong><small>{t.clientId?clientMap.get(t.clientId)?.name:t.leadId?leadMap.get(t.leadId)?.name:"Helz-One"} · {dateLabel(t.dueDate)}</small></div><button onClick={()=>void setTaskDone(t)}>Marcar hecha</button></div>)}
              {!unpaid.length&&!tasks.length&&<Empty title="Todo al día" body="Aquí aparecerán las cuotas pendientes y las tareas que anotes."/>}</div></div>
              <div className="panel"><div className="panel-head"><div><h2>Control de cuotas</h2><p>Mes de servicio: {month}</p></div><span className="mini-tag">{expected?Math.min(100,Math.round(monthlyPaid/expected*100)):0}% cobrado</span></div><div className="progress-track"><span style={{width:(expected?Math.min(100,monthlyPaid/expected*100):0)+"%"}}/></div><div className="split-stats"><div><small>Esperado</small><strong>{money(expected)}</strong></div><div><small>Registrado como cuota</small><strong>{money(monthlyPaid)}</strong></div></div><div className="panel-divider"/><div className="quick-actions"><button onClick={()=>openClient()}><b>＋</b><span>Alta de cliente</span></button><button onClick={()=>open("task",{dueDate:today()})}><b>✓</b><span>Nueva tarea</span></button><button onClick={()=>open("transaction",{transactionDate:today(),direction:"entrada",category:"Cuota mensual",servicePeriod:month})}><b>€</b><span>Movimiento de caja</span></button><button onClick={()=>open("lead",{stage:"nuevo",nextActionDate:today()})}><b>＋</b><span>Contacto potencial</span></button></div></div></div>
            <div className="panel table-panel"><div className="panel-head"><div><h2>Movimientos recientes</h2><p>Registro de caja · {month}</p></div><button className="link-button" onClick={()=>setPage("caja")}>Abrir caja →</button></div><TransactionTable transactions={monthTx.slice(0,6)} clients={clientMap}/></div>
          </section>}
          {page==="clientes"&&<section><div className="page-heading"><div><div className="eyebrow">RELACIÓN Y SERVICIO</div><h1>Clientes</h1><p>Fichas, objetivos y servicio de cada cliente.</p></div><button className="button button-primary" onClick={()=>openClient()}>＋ Añadir cliente</button></div>
            {selected?<ClientDetail client={selected} transactions={data.transactions.filter(t=>t.clientId===selected.id)} tanitaAssessments={data.tanitaAssessments.filter(a=>a.clientId===selected.id)} professionalNotes={data.professionalNotes.filter(n=>n.clientId===selected.id)} onBack={()=>setSelected(null)} onEdit={()=>openClient(selected)} onTanita={()=>openTanita(selected)} onArchive={()=>void toggleStatus(selected)} onDelete={()=>void deleteClient(selected)}/>:<><div className="toolbar"><input className="search-input" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar cliente, teléfono o servicio…"/><span className="muted">{filtered.length} registros</span></div><div className="panel table-panel"><ClientTable clients={filtered} onSelect={setSelected} onDelete={(c)=>void deleteClient(c)}/></div></>}
          </section>}
          {page==="pagos"&&<section><div className="page-heading"><div><div className="eyebrow">CUOTAS Y COBROS</div><h1>Pagos del mes</h1><p>Cada mes comienza con las cuotas activas pendientes. Los cobros parciales también quedan registrados.</p></div><label className="toolbar-label">Mes <input className="month-input" type="month" value={month} onChange={e=>{setLoading(true);setMonth(e.target.value);}}/></label></div><div className="metrics metrics-three"><Metric label="Cuotas previstas" value={money(expected)} detail={data.monthlyDues.length+" clientes incluidos"} icon="€"/><Metric label="Cobrado" value={money(monthlyPaid)} detail="Pagos aplicados a este mes" icon="↘" gold/><Metric label="Pendiente" value={money(Math.max(0,expected-monthlyPaid))} detail={unpaid.length+" clientes con saldo"} icon="◷"/></div><div className="panel table-panel"><div className="panel-head"><div><h2>Estado por cliente</h2><p>El importe previsto queda guardado para este mes aunque luego cambie la cuota habitual.</p></div></div><div className="table-scroll"><table><thead><tr><th>Cliente</th><th>Cuota de {month}</th><th>Pagado</th><th>Pendiente</th><th>Estado</th><th></th></tr></thead><tbody>{data.monthlyDues.map(d=>{const c=clientMap.get(d.clientId);if(!c)return null;const paid=paidByClient.get(c.id)||0;const balance=Math.max(0,d.amountDueCents-paid);const status=d.amountDueCents===0?"Cuota por definir":balance===0?"Pagado":paid>0?"Parcial":"Pendiente";return <tr key={d.id}><td><strong>{c.name}</strong><small>{c.feeFrozen?"Cuota congelada":""}</small></td><td>{d.amountDueCents?money(d.amountDueCents):"Por definir"}</td><td>{money(paid)}</td><td>{money(balance)}</td><td><span className={"status-pill "+(balance===0&&d.amountDueCents>0?"active":paid>0?"paused":"inactive")}>{status}</span></td><td>{balance>0&&d.amountDueCents>0&&<button className="reconcile-button" onClick={()=>open("transaction",{direction:"entrada",category:"Cuota mensual",clientId:c.id,amount:(balance/100).toFixed(2),servicePeriod:month,transactionDate:today(),paymentMethod:c.paymentMethod})}>Registrar pago</button>}</td></tr>})}{!data.monthlyDues.length&&<tr><td colSpan={6}><Empty title="No hay cuotas previstas" body="Da de alta clientes activos para que aparezcan automáticamente en cada mes."/></td></tr>}</tbody></table></div></div></section>}
          {page==="tareas"&&<section><div className="page-heading"><div><div className="eyebrow">ORGANIZACIÓN DEL CENTRO</div><h1>Tareas</h1><p>Apunta llamadas, compras y pendientes del centro para otro momento.</p></div><button className="button button-primary" onClick={()=>open("task",{dueDate:today()})}>＋ Nueva tarea</button></div><div className="panel"><div className="panel-head"><div><h2>Pendientes</h2><p>Ordenadas por fecha límite</p></div></div><div className="task-list">{tasks.map(t=><TaskRow key={t.id} task={t} clientName={(t.clientId?clientMap.get(t.clientId)?.name:t.leadId?leadMap.get(t.leadId)?.name:"Centro")??"Registro no disponible"} onDone={()=>void setTaskDone(t)}/>)}{!tasks.length&&<Empty title="Sin tareas pendientes" body="Añade aquí los pendientes del centro cuando lo necesites."/>}</div></div></section>}
          {page==="leads"&&<section><div className="page-heading"><div><div className="eyebrow">CRECIMIENTO DEL CENTRO</div><h1>Captación</h1><p>Oportunidades y próximos contactos en un solo sitio.</p></div><button className="button button-primary" onClick={()=>open("lead",{stage:"nuevo",nextActionDate:today()})}>＋ Nuevo contacto</button></div><div className="pipeline">{stages.slice(0,6).map(([stage,label])=>{const list=data.leads.filter(l=>l.stage===stage);return <div className="pipeline-column" key={stage}><div className="pipeline-title"><span>{label}</span><b>{list.length}</b></div>{list.map(l=><article className="lead-card" key={l.id}><strong>{l.name}</strong><span>{l.objective||"Objetivo pendiente"}</span><small>{l.source||"Origen sin indicar"} · {dateLabel(l.nextActionDate)}</small><select value={l.stage} onChange={e=>void setStage(l,e.target.value)} aria-label={"Cambiar etapa de "+l.name}>{stages.map(([v,t])=><option key={v} value={v}>{t}</option>)}</select></article>)}{!list.length&&<div className="pipeline-empty">Sin contactos</div>}</div>;})}</div></section>}
        {page==="caja"&&<section><div className="page-heading"><div><div className="eyebrow">CONTROL INTERNO DE TESORERÍA</div><h1>Caja</h1><p>Registra cada cobro y gasto con fecha, categoría y justificante.</p></div><button className="button button-primary" onClick={()=>open("transaction",{transactionDate:today(),direction:"entrada",category:"Cuota mensual",servicePeriod:month})}>＋ Registrar movimiento</button></div><div className="toolbar"><label className="toolbar-label">Periodo <input className="month-input" type="month" value={month} onChange={e=>{setLoading(true);setMonth(e.target.value);}}/></label><button className="button button-secondary button-small" onClick={exportBackup}>↓ Copia completa</button></div><div className="metrics metrics-three"><Metric label="Entradas" value={money(cashIn)} detail="Dinero recibido" icon="↘" gold/><Metric label="Salidas" value={money(cashOut)} detail="Dinero pagado" icon="↗"/><Metric label="Neto" value={money(cashIn-cashOut)} detail="Entradas − salidas" icon="＝"/></div><div className="panel table-panel"><div className="panel-head"><div><h2>Libro de caja</h2><p>{monthTx.length} movimientos · El historial queda conservado</p></div></div><TransactionTable transactions={monthTx} clients={clientMap} onReconcile={t=>void save("transaction",{reconciled:!t.reconciled},t.id)}/></div><div className="accounting-note"><strong>Control interno</strong><span>Este registro ayuda a controlar los movimientos del centro. Mantén la contabilidad y los libros oficiales coordinados con la asesoría fiscal.</span></div></section>}
          {page==="venta-cruzada"&&<section><div className="page-heading"><div><div className="eyebrow">NUEVAS VÍAS DE INGRESO</div><h1>Venta cruzada</h1><p>Simula ingresos y margen mensual para valoraciones, merchandising y otros servicios.</p></div><div className="cross-sell-actions"><button className="button button-primary" onClick={()=>openOffer()}>＋ Añadir oferta</button></div></div><div className="metrics"><Metric label="Ingresos potenciales / mes" value={money(projectedRevenue)} detail="Precio × unidades previstas" icon="↗" gold/><Metric label="Coste variable / mes" value={money(projectedVariableCost)} detail="Coste por unidad × unidades" icon="−"/><Metric label="Margen bruto potencial" value={money(projectedMargin)} detail="Antes de gastos fijos e impuestos" icon="＝" gold/><Metric label="Inversión inicial prevista" value={money(plannedInvestment)} detail="Equipo y puesta en marcha" icon="€"/></div><div className="panel table-panel"><div className="panel-head"><div><h2>Servicios y productos</h2><p>Las ofertas planificadas y activas forman parte de la estimación; las pausadas y archivadas quedan fuera.</p></div></div><CrossSellTable offers={data.crossSellOffers} onEdit={offer=>openOffer(offer)} onArchive={offer=>void archiveOffer(offer)}/></div><div className="accounting-note"><strong>Cómo leer la previsión</strong><span>El margen descuenta el coste variable declarado. La inversión inicial no se resta del margen mensual ni incluye gastos fijos, impuestos o comisiones; registra compras reales también en Caja.</span></div></section>}
        {page==="suplementacion"&&<section><div className="page-heading"><div><div className="eyebrow">PLANIFICACIÓN MENSUAL</div><h1>Suplementación</h1><p>Introduce cuánto inviertes en producto; calculo el retorno al doble y el beneficio estimado.</p></div><label className="toolbar-label">Mes <input className="month-input" type="month" value={month} onChange={e=>{setLoading(true);setMonth(e.target.value);}}/></label></div><div className="supplement-planner"><div className="panel supplement-input-panel"><div className="panel-head"><div><h2>Inversión en producto</h2><p>Importe total destinado a suplementos este mes</p></div><span className="supplement-factor">×2 retorno</span></div><div className="supplement-input-body"><label className="supplement-amount-label" htmlFor="supplement-investment">¿Cuánto pones este mes?</label><div className="supplement-money-input"><input id="supplement-investment" type="number" min="0" step="0.01" value={supplementInvestment} onChange={e=>setSupplementDraft({month,plans:data.supplementPlans,value:e.target.value})} placeholder="150"/><span>€</span></div><p>La previsión asume que vendes todo el producto y recuperas el doble de la inversión.</p><button className="button button-primary" disabled={saving} onClick={()=>void save("supplement_plan",{servicePeriod:month,investmentCents:supplementInvestmentCents},supplementPlan?.id)}>{saving?"Guardando…":"Guardar previsión del mes"}</button>{supplementPlan&&<span className="supplement-saved">Previsión guardada para {month}</span>}</div></div><div className="supplement-results"><Metric label="Inversión mensual" value={money(supplementInvestmentCents)} detail="Compra de producto" icon="−"/><Metric label="Retorno estimado" value={money(supplementReturnCents)} detail="Ventas previstas · ×2" icon="↗" gold/><Metric label="Beneficio estimado" value={money(supplementProfitCents)} detail="Retorno menos inversión" icon="＝" gold/></div></div><div className="accounting-note"><strong>Ejemplo</strong><span>Si inviertes 150 €, el retorno estimado es 300 € y el beneficio estimado 150 €. Registra en Caja las compras y ventas reales para compararlas con esta previsión.</span></div></section>}
        </>}
      </div>
    </main>
    {modal&&<div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setModal(null);}}><form className="modal-card" onSubmit={submit}><div className="modal-header"><div><div className="eyebrow">HELZ-ONE CRM</div><h2>{modal==="client"?(editing?"Editar ficha":"Alta de cliente"):modal==="lead"?"Nuevo contacto":modal==="transaction"?"Movimiento de caja":modal==="checkin"?"Seguimiento de sesión":modal==="crossSell"?(editingOffer?"Editar oferta":"Nueva oferta de venta cruzada"):modal==="tanita"?"Nueva valoración Tanita":"Nueva tarea"}</h2></div><button type="button" className="close-button" onClick={()=>setModal(null)}>×</button></div>
      {modal==="client"&&<div className="form-grid"><Field label="Nombre completo" full><input required value={formValue("name")} onChange={e=>field("name",e.target.value)} placeholder="Nombre y apellidos"/></Field><Field label="Teléfono"><input value={formValue("phone")} onChange={e=>field("phone",e.target.value)}/></Field><Field label="Correo"><input type="email" value={formValue("email")} onChange={e=>field("email",e.target.value)}/></Field><Field label="Servicio"><select value={formValue("service")} onChange={e=>field("service",e.target.value)}><option value="">Selecciona servicio</option>{services.map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></Field><Field label="Frecuencia semanal"><select value={formValue("frequency")} onChange={e=>field("frequency",e.target.value)}><option value="">Selecciona días por semana</option>{[1,2,3,4,5].map(n=><option key={n} value={n+""}>{n} {n===1?"día":"días"} / semana</option>)}</select></Field><Field label="Tipo de horario"><select value={formValue("scheduleType","fijo")} onChange={e=>field("scheduleType",e.target.value)}><option value="fijo">Fijo</option><option value="variable">Variable por turnos</option></select></Field><Field label="Días y horas de entrenamiento" full><textarea rows={2} value={formValue("trainingSchedule")} onChange={e=>field("trainingSchedule",e.target.value)} placeholder={formValue("scheduleType","fijo")==="variable"?"Ej. Depende del turno; confirmar cada semana":"Ej. Lunes 09:00 y jueves 18:00"}/></Field><Field label="Cuota mensual (€)"><input required type="number" min="0" step="0.01" value={formValue("monthlyFee")} disabled={!!editing&&!!form.feeFrozen} onChange={e=>field("monthlyFee",e.target.value)}/></Field><Field label="Método de pago"><select value={formValue("paymentMethod","efectivo")} onChange={e=>field("paymentMethod",e.target.value)}><option value="efectivo">Efectivo</option><option value="transferencia">Transferencia</option><option value="tarjeta">Tarjeta</option><option value="domiciliacion">Domiciliación</option><option value="otro">Otro</option></select></Field><Field label="Estado"><select value={formValue("status","active")} onChange={e=>field("status",e.target.value)}><option value="active">Activo</option><option value="paused">En pausa</option><option value="inactive">Baja / antiguo</option></select></Field><Field label="Fecha de alta"><input type="date" value={formValue("startDate")} onChange={e=>field("startDate",e.target.value)}/></Field><Field label="Notas importantes" full><input value={formValue("importantNotes")} onChange={e=>field("importantNotes",e.target.value)} placeholder="Ej. Ictus · hernia discal · menisco externo derecho"/></Field><Field label="Objetivo principal" full><select value={formValue("goal")} onChange={e=>field("goal",e.target.value)}><option value="">Selecciona el objetivo principal</option>{goals.map(goal=><option key={goal} value={goal}>{goal}</option>)}</select></Field><Field label="Notas de entrenamiento" full><textarea rows={3} value={formValue("trainingNotes")} onChange={e=>field("trainingNotes",e.target.value)} placeholder="Observaciones relevantes para el entrenamiento y el seguimiento."/></Field><Field label="Retos, marcas y métricas" full><textarea rows={4} value={formValue("trainingMetrics")} onChange={e=>field("trainingMetrics",e.target.value)} placeholder="Ej.: reto 1 km — 5:20; carrera 5 km — 29:10; fuerza de agarre; HRV; Tanita; marcas y fechas…"/></Field><Field label="Anotaciones de fisioterapia" full><textarea rows={4} value={formValue("physioNotes")} onChange={e=>field("physioNotes",e.target.value)} placeholder="Valoración funcional, evolución, molestias comunicadas, intervención y pautas acordadas…"/></Field><label className="consent-row"><input type="checkbox" checked={!!form.feeFrozen} onChange={e=>field("feeFrozen",e.target.checked)}/> Cuota congelada: bloquear cambios de precio hasta desmarcar esta opción</label><label className="consent-row"><input type="checkbox" checked={!!form.testimonialConsent} onChange={e=>field("testimonialConsent",e.target.checked)}/> Autorización para publicar testimonio o imagen confirmada</label></div>}
      {modal==="lead"&&<div className="form-grid"><Field label="Nombre" full><input required value={formValue("name")} onChange={e=>field("name",e.target.value)}/></Field><Field label="Teléfono o correo"><input value={formValue("contact")} onChange={e=>field("contact",e.target.value)}/></Field><Field label="Origen"><input value={formValue("source")} onChange={e=>field("source",e.target.value)} placeholder="Referido, redes, antiguo cliente…"/></Field><Field label="Objetivo" full><input value={formValue("objective")} onChange={e=>field("objective",e.target.value)}/></Field><Field label="Etapa"><select value={formValue("stage","nuevo")} onChange={e=>field("stage",e.target.value)}>{stages.map(([v,t])=><option key={v} value={v}>{t}</option>)}</select></Field><Field label="Próximo contacto"><input type="date" value={formValue("nextActionDate")} onChange={e=>field("nextActionDate",e.target.value)}/></Field><Field label="Notas" full><textarea rows={3} value={formValue("notes")} onChange={e=>field("notes",e.target.value)}/></Field></div>}
      {modal==="transaction"&&<div className="form-grid"><Field label="Tipo"><select value={formValue("direction","entrada")} onChange={e=>{field("direction",e.target.value);field("category",e.target.value==="salida"?"Otros gastos":"Otros ingresos");}}><option value="entrada">Entrada</option><option value="salida">Salida</option></select></Field><Field label="Importe (€)"><input required type="number" min="0.01" step="0.01" value={formValue("amount")} onChange={e=>field("amount",e.target.value)}/></Field><Field label="Fecha"><input required type={form.datePrecision==="month"?"month":"date"} value={formValue("transactionDate",today())} onChange={e=>field("transactionDate",e.target.value)}/></Field><label className="consent-row full"><input type="checkbox" checked={form.datePrecision==="month"} onChange={e=>{const monthly=e.target.checked;field("datePrecision",monthly?"month":"day");field("transactionDate",monthly?formValue("transactionDate",today()).slice(0,7):formValue("transactionDate",today()).length===7?formValue("transactionDate")+"-01":formValue("transactionDate",today()));}}/> No conozco el día exacto</label><Field label="Categoría"><select value={formValue("category","Cuota mensual")} onChange={e=>field("category",e.target.value)}><option>Cuota mensual</option><option>Entrenamiento personal</option><option>Valoración</option><option>Nutrición</option><option>Venta cruzada</option><option>Alquiler</option><option>Suministros</option><option>Nómina / colaboración</option><option>Material</option><option>Asesoría / gestoría</option><option>Impuestos y tasas</option><option>Comisiones bancarias</option><option>Otros ingresos</option><option>Otros gastos</option></select></Field><Field label="Cliente (opcional)"><select value={formValue("clientId")} onChange={e=>field("clientId",e.target.value)}><option value="">Sin cliente asociado</option>{data.clients.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field><Field label="Método"><select value={formValue("paymentMethod","efectivo")} onChange={e=>field("paymentMethod",e.target.value)}><option value="efectivo">Efectivo</option><option value="transferencia">Transferencia</option><option value="tarjeta">Tarjeta</option><option value="domiciliacion">Domiciliación</option><option value="otro">Otro</option></select></Field><Field label="Mes de servicio"><input type="month" value={formValue("servicePeriod")} onChange={e=>field("servicePeriod",e.target.value)}/></Field><Field label="Nº factura / justificante"><input value={formValue("reference")} onChange={e=>field("reference",e.target.value)}/></Field><Field label="Concepto" full><textarea rows={2} value={formValue("description")} onChange={e=>field("description",e.target.value)} placeholder="Describe el movimiento."/></Field><p className="form-hint full">Los movimientos guardados se mantienen en el historial. Para corregir uno, registra un ajuste con su justificante.</p></div>}
      {modal==="checkin"&&<div className="form-grid"><Field label="Cliente" full><select required value={formValue("clientId")} onChange={e=>field("clientId",e.target.value)}><option value="">Selecciona cliente</option>{active.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field><Field label="Fecha"><input required type="date" value={formValue("sessionDate",today())} onChange={e=>field("sessionDate",e.target.value)}/></Field><Field label="Tipo"><select value={formValue("sessionType","Entrenamiento")} onChange={e=>field("sessionType",e.target.value)}><option>Entrenamiento</option><option>Readaptación</option><option>Valoración</option><option>Revisión</option><option>Otro</option></select></Field><Field label="Asistencia"><select value={formValue("attendance","realizada")} onChange={e=>field("attendance",e.target.value)}><option value="realizada">Realizada</option><option value="cancelada">Cancelada</option><option value="no-show">No asistió</option></select></Field><Field label="Esfuerzo (1–10)"><input type="number" min="1" max="10" value={formValue("effort")} onChange={e=>field("effort",e.target.value)}/></Field><Field label="Satisfacción (1–10)"><input type="number" min="1" max="10" value={formValue("satisfaction")} onChange={e=>field("satisfaction",e.target.value)}/></Field><Field label="Molestia (0–10)"><input type="number" min="0" max="10" value={formValue("discomfort")} onChange={e=>field("discomfort",e.target.value)}/></Field><Field label="Próxima revisión"><input type="date" value={formValue("followupDate")} onChange={e=>field("followupDate",e.target.value)}/></Field><Field label="Observaciones" full><textarea rows={3} value={formValue("notes")} onChange={e=>field("notes",e.target.value)}/></Field><Field label="Siguiente paso" full><input value={formValue("nextAction")} onChange={e=>field("nextAction",e.target.value)} placeholder="Ajustar carga, revisar técnica, contactar…"/></Field></div>}
      {modal==="tanita"&&<div className="form-grid"><div className="tanita-price full"><strong>Valoración Tanita · 20 €</strong><span>Quedará guardada en la ficha de {selected?.name||"este cliente"}.</span></div><Field label="Fecha de valoración"><input required type="date" value={formValue("assessmentDate",today())} onChange={e=>field("assessmentDate",e.target.value)}/></Field><Field label="Peso (kg)"><input type="number" min="0" max="500" step="0.1" value={formValue("weightKg")} onChange={e=>field("weightKg",e.target.value)}/></Field><Field label="Grasa corporal (%)"><input type="number" min="0" max="100" step="0.1" value={formValue("bodyFatPercent")} onChange={e=>field("bodyFatPercent",e.target.value)}/></Field><Field label="Masa muscular (kg)"><input type="number" min="0" max="300" step="0.1" value={formValue("muscleMassKg")} onChange={e=>field("muscleMassKg",e.target.value)}/></Field><Field label="Grasa visceral"><input type="number" min="0" max="100" step="1" value={formValue("visceralFat")} onChange={e=>field("visceralFat",e.target.value)}/></Field><Field label="IMC"><input type="number" min="0" max="100" step="0.1" value={formValue("bmi")} onChange={e=>field("bmi",e.target.value)}/></Field><Field label="Metabolismo basal (kcal)"><input type="number" min="0" max="10000" step="1" value={formValue("basalMetabolismKcal")} onChange={e=>field("basalMetabolismKcal",e.target.value)}/></Field><Field label="Agua corporal (%)"><input type="number" min="0" max="100" step="0.1" value={formValue("bodyWaterPercent")} onChange={e=>field("bodyWaterPercent",e.target.value)}/></Field><Field label="Notas" full><textarea rows={2} value={formValue("tanitaNotes")} onChange={e=>field("tanitaNotes",e.target.value)} placeholder="Observaciones de esta medición…"/></Field><label className="consent-row"><input type="checkbox" checked={!!form.paid} onChange={e=>field("paid",e.target.checked)}/> Cobrado · registrar automáticamente los 20 € en Caja</label>{!!form.paid&&<Field label="Método de pago"><select value={formValue("paymentMethod","efectivo")} onChange={e=>field("paymentMethod",e.target.value)}><option value="efectivo">Efectivo</option><option value="transferencia">Transferencia</option><option value="tarjeta">Tarjeta</option><option value="domiciliacion">Domiciliación</option><option value="otro">Otro</option></select></Field>}</div>}
      {modal==="task"&&<div className="form-grid"><Field label="Acción" full><input required value={formValue("title")} onChange={e=>field("title",e.target.value)} placeholder="Llamar, revisar progreso, enviar propuesta…"/></Field><Field label="Fecha límite"><input required type="date" value={formValue("dueDate",today())} onChange={e=>field("dueDate",e.target.value)}/></Field><Field label="Cliente"><select value={formValue("clientId")} onChange={e=>field("clientId",e.target.value)}><option value="">Sin cliente</option>{data.clients.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field><Field label="Contacto potencial" full><select value={formValue("leadId")} onChange={e=>field("leadId",e.target.value)}><option value="">Sin contacto potencial</option>{data.leads.map(l=><option key={l.id} value={l.id}>{l.name}</option>)}</select></Field><Field label="Notas" full><textarea rows={3} value={formValue("notes")} onChange={e=>field("notes",e.target.value)}/></Field></div>}
      {modal==="crossSell"&&<div className="form-grid"><Field label="Nombre de la oferta" full><input required value={formValue("name")} onChange={e=>field("name",e.target.value)} placeholder="Ej. Valoración funcional con Tanita"/></Field><Field label="Tipo"><select value={formValue("category","otro")} onChange={e=>field("category",e.target.value)}><option value="valoracion">Valoración funcional</option><option value="merchandising">Merchandising</option><option value="otro">Otro</option></select></Field><Field label="Estado"><select value={formValue("status","planificada")} onChange={e=>field("status",e.target.value)}><option value="planificada">Planificada</option><option value="activa">Activa</option><option value="pausada">Pausada</option><option value="archivada">Archivada</option></select></Field><Field label="Precio por unidad (€)"><input required type="number" min="0" step="0.01" value={formValue("unitPrice")} onChange={e=>field("unitPrice",e.target.value)}/></Field><Field label="Coste variable por unidad (€)"><input required type="number" min="0" step="0.01" value={formValue("unitCost","0")} onChange={e=>field("unitCost",e.target.value)}/></Field><Field label="Unidades previstas al mes"><input required type="number" min="0" step="1" value={formValue("expectedUnits","0")} onChange={e=>field("expectedUnits",e.target.value)}/></Field><Field label="Inversión inicial (€)"><input required type="number" min="0" step="0.01" value={formValue("initialInvestment","0")} onChange={e=>field("initialInvestment",e.target.value)}/></Field><Field label="Notas" full><textarea rows={3} value={formValue("notes")} onChange={e=>field("notes",e.target.value)} placeholder="Lanzamiento, proveedor, público objetivo o detalles de la oferta…"/></Field><p className="form-hint full">Puedes dejar la previsión mensual en 0 hasta decidir cuántas ventas o valoraciones estimas. El coste de una máquina va en inversión inicial, no en coste variable.</p></div>}
      {error&&<div className="notice notice-error form-error">{error}</div>}<div className="modal-footer"><button type="button" className="button button-secondary" onClick={()=>setModal(null)}>Cancelar</button><button disabled={saving} className="button button-primary">{saving?"Guardando…":"Guardar"}</button></div>
    </form></div>}
  </div>;
}

function Metric({label,value,detail,icon,gold=false}:{label:string;value:string;detail:string;icon:string;gold?:boolean}){return <article className="metric-card"><div className="metric-top"><span>{label}</span><b className={gold?"gold-icon":""}>{icon}</b></div><strong className={gold?"metric-value gold-text":"metric-value"}>{value}</strong><small>{detail}</small></article>}
function Field({label,full,children}:{label:string;full?:boolean;children:React.ReactNode}){return <label className={"form-field "+(full?"full":"")}><span>{label}</span>{children}</label>}
function Empty({title,body}:{title:string;body:string}){return <div className="empty-state"><span>✦</span><strong>{title}</strong><p>{body}</p></div>}
function ClientTable({clients,onSelect,onDelete}:{clients:Client[];onSelect:(c:Client)=>void;onDelete:(c:Client)=>void}){if(!clients.length)return <Empty title="Aún no hay clientes" body="Empieza creando una ficha nueva. El CRM comienza vacío."/>;return <div className="table-scroll"><table><thead><tr><th>Cliente</th><th>Servicio</th><th>Frecuencia</th><th>Horario</th><th>Cuota mensual</th><th>Estado</th><th>Notas importantes</th><th>Acción</th></tr></thead><tbody>{clients.map(c=><tr key={c.id} onClick={()=>onSelect(c)} className={"click-row client-row-"+c.status}><td><strong className="client-name">{c.name}{c.status==="active"&&<span className="active-check" aria-label="Cliente activo" title="Cliente activo">✓</span>}</strong><small>{c.email||c.phone||"Sin datos de contacto"}</small></td><td>{c.service||"—"}</td><td>{frequencyLabel(c.frequency)}</td><td>{c.scheduleType==="variable"?"Variable":c.trainingSchedule||"—"}</td><td>{money(c.monthlyFeeCents)}</td><td><span className={"status-pill "+c.status}>{c.status==="active"?"Activo":c.status==="paused"?"En pausa":"Antiguo"}</span></td><td className="important-notes-cell">{c.importantNotes?.trim()||"—"}</td><td><button className="delete-client-button" onClick={e=>{e.stopPropagation();onDelete(c);}}>Borrar</button></td></tr>)}</tbody></table></div>}
function CrossSellTable({offers,onEdit,onArchive}:{offers:CrossSellOffer[];onEdit:(offer:CrossSellOffer)=>void;onArchive:(offer:CrossSellOffer)=>void}){if(!offers.length)return <Empty title="Aún no hay ofertas" body="Añade una valoración, un producto o un servicio para empezar a calcular su potencial."/>;const categoryLabels:Record<string,string>={valoracion:"Valoración funcional",suplementacion:"Suplementación",merchandising:"Merchandising",otro:"Otro"};const statusLabels:Record<string,string>={planificada:"Planificada",activa:"Activa",pausada:"Pausada",archivada:"Archivada"};return <div className="table-scroll"><table><thead><tr><th>Oferta</th><th>Estado</th><th>Precio</th><th>Unidades / mes</th><th>Ingresos potenciales</th><th>Margen estimado</th><th>Ventas para cubrir inversión</th><th></th></tr></thead><tbody>{offers.map(o=>{const revenue=o.unitPriceCents*o.expectedUnits;const margin=(o.unitPriceCents-o.unitCostCents)*o.expectedUnits;const contribution=o.unitPriceCents-o.unitCostCents;const breakeven=o.initialInvestmentCents>0&&contribution>0?Math.ceil(o.initialInvestmentCents/contribution):null;return <tr key={o.id}><td><strong>{o.name}</strong><small>{categoryLabels[o.category]||"Otro"}{o.notes?" · "+o.notes:""}</small></td><td><span className={"status-pill "+(o.status==="activa"?"active":o.status==="pausada"?"paused":o.status==="archivada"?"inactive":"")}>{statusLabels[o.status]||o.status}</span></td><td>{money(o.unitPriceCents)}</td><td>{o.expectedUnits}</td><td>{money(revenue)}</td><td className="amount entrada">{money(margin)}</td><td>{breakeven===null?"—":`${breakeven} unidades`}</td><td className="offer-actions"><button className="reconcile-button" onClick={()=>onEdit(o)}>Editar</button>{o.status!=="archivada"&&<button className="reconcile-button archive-offer" onClick={()=>onArchive(o)}>Archivar</button>}</td></tr>;})}</tbody></table></div>}
function TransactionTable({transactions,clients,onReconcile}:{transactions:Transaction[];clients:Map<string,Client>;onReconcile?:(t:Transaction)=>void}){if(!transactions.length)return <Empty title="Sin movimientos en este periodo" body="Registra cada cobro y gasto para construir una visión fiable de la caja."/>;return <div className="table-scroll"><table><thead><tr><th>Fecha</th><th>Movimiento</th><th>Detalle</th><th>Cliente</th><th>Periodo</th><th className="align-right">Importe</th><th>Justificante</th><th>Banco</th></tr></thead><tbody>{transactions.map(t=><tr key={t.id}><td>{dateLabel(t.transactionDate)}</td><td><span className={"movement "+t.direction}>{t.direction==="entrada"?"Entrada":"Salida"}</span></td><td><strong>{t.category}</strong><small>{t.description||t.paymentMethod||"—"}</small></td><td>{t.clientId?clients.get(t.clientId)?.name||"Cliente archivado":"—"}</td><td>{t.servicePeriod||"—"}</td><td className={"align-right amount "+t.direction}>{t.direction==="salida"?"−":"+"}{money(t.amountCents)}</td><td>{t.reference||"—"}</td><td>{onReconcile?<button className="reconcile-button" onClick={()=>onReconcile(t)}>{t.reconciled?"✓ Conciliado":"Marcar"}</button>:t.reconciled?"✓":"Pendiente"}</td></tr>)}</tbody></table></div>}
function TaskRow({task,clientName,onDone}:{task:Task;clientName:string;onDone:()=>void}){const late=task.dueDate<today();return <div className="task-row"><span className={"task-check "+(late?"late":"")}>◷</span><div><strong>{task.title}</strong><small>{clientName} · {dateLabel(task.dueDate)}{late?" · Vencida":""}</small>{task.notes&&<p>{task.notes}</p>}</div><button onClick={onDone} aria-label="Marcar tarea como hecha">✓</button></div>}
function ClientDetail({client,transactions,tanitaAssessments,professionalNotes,onBack,onEdit,onTanita,onArchive,onDelete}:{client:Client;transactions:Transaction[];tanitaAssessments:TanitaAssessment[];professionalNotes:ProfessionalNote[];onBack:()=>void;onEdit:()=>void;onTanita:()=>void;onArchive:()=>void;onDelete:()=>void}) {
  const total=transactions.filter(t=>t.direction==="entrada").reduce((sum,t)=>sum+t.amountCents,0);
  const tanitaHistory=[...tanitaAssessments].sort((a,b)=>b.assessmentDate.localeCompare(a.assessmentDate));
  const latestTanita=tanitaHistory[0];
  const previousTanita=tanitaHistory[1];
  return <div className="client-detail">
    <button className="back-button" onClick={onBack}>← Volver a clientes</button>
    <div className="detail-hero"><div><div className="eyebrow">FICHA DE CLIENTE</div><h1>{client.name}</h1><p>{client.service||"Servicio por definir"} · {client.status==="active"?"Activo":client.status==="paused"?"En pausa":"Antiguo"}</p></div><div className="detail-actions"><button className="button button-secondary" onClick={onArchive}>{client.status==="inactive"?"Reactivar":"Archivar"}</button><button className="button button-secondary" onClick={onTanita}>＋ Tanita · 20 €</button><button className="button button-primary" onClick={onEdit}>Editar ficha</button><button className="button delete-client-button" onClick={onDelete}>Borrar cliente</button></div></div>
    <div className="metrics metrics-three"><Metric label="Cuota mensual" value={money(client.monthlyFeeCents)} detail={"Método: "+(client.paymentMethod==="efectivo"?"Efectivo":client.paymentMethod||"—")} icon="€" gold/><Metric label="Frecuencia" value={frequencyLabel(client.frequency)} detail="Sesiones previstas" icon="↗"/><Metric label="Cobrado en historial" value={money(total)} detail={transactions.length+" movimientos"} icon="↘"/></div>
    <div className="panel"><div className="panel-head"><div><h2>Información y objetivos</h2><p>Datos para organizar el servicio</p></div></div><div className="profile-list"><Profile label="Teléfono" value={client.phone}/><Profile label="Correo" value={client.email}/><Profile label="Horario" value={(client.scheduleType==="variable"?"Variable · ":"Fijo · ")+(client.trainingSchedule||"Por definir")}/><Profile label="Alta" value={dateLabel(client.startDate)}/><Profile label="Notas importantes" value={client.importantNotes}/><Profile label="Objetivo" value={client.goal}/><Profile label="Notas de entrenamiento" value={client.trainingNotes}/><Profile label="Retos y métricas" value={client.trainingMetrics}/><Profile label="Anotaciones de fisioterapia" value={client.physioNotes}/><Profile label="Autorización de testimonio" value={client.testimonialConsent?"Confirmada":"No registrada"}/></div></div>
    {professionalNotes.length>0&&<div className="panel table-panel pro-notes-owner"><div className="panel-head"><div><h2>Historial profesional</h2><p>Notas registradas desde los accesos de fisioterapia y podología</p></div><span className="mini-tag">{professionalNotes.length} anotaciones</span></div><div className="task-list">{professionalNotes.map(note=><div className="history-row" key={note.id}><strong>{note.professionalRole==="fisioterapia"?"Fisioterapia":"Podología"} · {dateLabel(note.createdAt.slice(0,10))}</strong><small>{new Date(note.createdAt).toLocaleTimeString("es-ES",{hour:"2-digit",minute:"2-digit"})}</small><p>{note.note}</p></div>)}</div></div>}
    {latestTanita&&<div className="panel tanita-comparison"><div className="panel-head"><div><h2>Evolución Tanita</h2><p>{previousTanita?`${dateLabel(previousTanita.assessmentDate)} → ${dateLabel(latestTanita.assessmentDate)} · variación frente a la medición anterior`:`Última medición · ${dateLabel(latestTanita.assessmentDate)} · añade otra valoración para ver cambios`}</p></div><span className="mini-tag">{tanitaHistory.length} {tanitaHistory.length===1?"medición":"mediciones"}</span></div><div className="tanita-comparison-grid"><TanitaDelta label="Peso" current={latestTanita.weightKg} previous={previousTanita?.weightKg??null} unit="kg"/><TanitaDelta label="Grasa corporal" current={latestTanita.bodyFatPercent} previous={previousTanita?.bodyFatPercent??null} unit="%"/><TanitaDelta label="Masa muscular" current={latestTanita.muscleMassKg} previous={previousTanita?.muscleMassKg??null} unit="kg"/><TanitaDelta label="Grasa visceral" current={latestTanita.visceralFat} previous={previousTanita?.visceralFat??null} unit="" digits={0}/><TanitaDelta label="IMC" current={latestTanita.bmi} previous={previousTanita?.bmi??null} unit=""/><TanitaDelta label="Metabolismo basal" current={latestTanita.basalMetabolismKcal} previous={previousTanita?.basalMetabolismKcal??null} unit="kcal" digits={0}/><TanitaDelta label="Agua corporal" current={latestTanita.bodyWaterPercent} previous={previousTanita?.bodyWaterPercent??null} unit="%"/></div><div className="tanita-compare-note">La variación solo compara los valores anotados en ambas fechas.</div></div>}
    <div className="panel table-panel tanita-history"><div className="panel-head"><div><h2>Valoraciones Tanita</h2><p>{tanitaAssessments.length} {tanitaAssessments.length===1?"valoración registrada":"valoraciones registradas"} · 20 € cada una</p></div><button className="button button-secondary button-small" onClick={onTanita}>＋ Añadir valoración</button></div>
      {tanitaHistory.length?<div className="table-scroll"><table><thead><tr><th>Fecha</th><th>Peso</th><th>Grasa corporal</th><th>Masa muscular</th><th>Grasa visceral</th><th>IMC</th><th>Metabolismo basal</th><th>Agua corporal</th><th>Cobro</th></tr></thead><tbody>{tanitaHistory.map(a=><tr key={a.id}><td>{dateLabel(a.assessmentDate)}</td><td>{a.weightKg==null?"—":`${a.weightKg} kg`}</td><td>{a.bodyFatPercent==null?"—":`${a.bodyFatPercent}%`}</td><td>{a.muscleMassKg==null?"—":`${a.muscleMassKg} kg`}</td><td>{a.visceralFat??"—"}</td><td>{a.bmi??"—"}</td><td>{a.basalMetabolismKcal==null?"—":`${a.basalMetabolismKcal} kcal`}</td><td>{a.bodyWaterPercent==null?"—":`${a.bodyWaterPercent}%`}</td><td><span className={"status-pill "+(a.paid?"active":"inactive")}>{a.paid?"Cobrado · 20 €":"Pendiente · 20 €"}</span></td></tr>)}</tbody></table>{tanitaHistory.some(a=>a.notes)&&<div className="tanita-notes">{tanitaHistory.filter(a=>a.notes).map(a=><p key={a.id}><strong>{dateLabel(a.assessmentDate)}:</strong> {a.notes}</p>)}</div>}</div>:<Empty title="Sin valoraciones" body="Añade la primera medición Tanita para guardar sus datos y fecha en esta ficha."/>}
    </div>
  </div>;
}
function TanitaDelta({label,current,previous,unit,digits=1}:{label:string;current:number|null;previous:number|null;unit:string;digits?:number}){const format=(value:number)=>`${value.toFixed(digits)}${unit?` ${unit}`:""}`;const delta=current!==null&&previous!==null?current-previous:null;return <article className="tanita-delta"><span>{label}</span><strong>{current===null?"—":format(current)}</strong><small>{delta===null?"Sin dato anterior":`Anterior ${format(previous!)} · ${delta>0?"+":""}${format(delta)}`}</small></article>}
function Profile({label,value}:{label:string;value?:string|null}){return <div className="profile-row"><span>{label}</span><strong>{value||"—"}</strong></div>}
